use moloch_live_runtime::package_not_sent_evidence;
use baal_transport_service::admission::{AccountAdmission,ImmutableBinding};
use serde_json::{Value,json};
#[test]fn wrapper_attestation_comes_from_actual_private_queue_completion_only(){let dir=std::env::temp_dir().join(format!("not-sent-wrapper-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let binding=ImmutableBinding{intent:"run:package".into(),key:"stable-key".into(),payload_hash:"a".repeat(64)};{let mut queue=AccountAdmission::open(&dir,"fixture","owner").unwrap();let command=|op:&str,now:u64|json!({"op":op,"scope":"fixture","now":now,"request":"request-1","write":true,"binding":binding,"authorized":true,"lease_valid":true,"permit_valid":true,"outcome":"not_sent"});queue.command(command("status",0)).unwrap();assert!(package_not_sent_evidence::VerifiedNotSent::read(&dir,"fixture",&binding,"request-1",0).is_err());queue.command(command("admit",10)).unwrap();queue.command(command("complete",20)).unwrap();let proof=package_not_sent_evidence::VerifiedNotSent::read(&dir,"fixture",&binding,"request-1",10).unwrap();let a=proof.attestation().unwrap();assert_eq!(a.request,"request-1");assert_eq!(a.completion["networkStarted"],false);assert_eq!(a.state["active"],Value::Null);assert_eq!(a.completion["binding"],serde_json::to_value(binding).unwrap());}std::fs::remove_dir_all(dir).unwrap();}
